BEFORE INSERT OR UPDATE OR DELETE ON public.document_processing_runs
FOR EACH ROW EXECUTE FUNCTION public.guard_knowledge_manifest_run();
CREATE CONSTRAINT TRIGGER knowledge_manifest_run_integrity
AFTER INSERT OR UPDATE OR DELETE ON public.document_processing_runs
DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION public.check_knowledge_manifest_run();
-- SOURCE security.sql sha256=42237a1a59973e731a6977a484f336ca64a414248ba3764e498133e4ca1019c0
DO $$
DECLARE relation_name text; revision_id uuid;
BEGIN
    FOREACH relation_name IN ARRAY ARRAY[
        'knowledge_source_revisions', 'knowledge_source_revision_audiences',
        'knowledge_source_revision_documents'
    ] LOOP
        EXECUTE format('ALTER TABLE public.%I OWNER TO postgres', relation_name);
        EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY', relation_name);
        EXECUTE format('REVOKE ALL ON TABLE public.%I FROM PUBLIC, anon, authenticated, service_role', relation_name);
        EXECUTE format('GRANT SELECT ON TABLE public.%I TO service_role', relation_name);
    END LOOP;
    -- Bootstrap rows predate the triggers: verify them before committing.
    FOR revision_id IN SELECT r.revision_id FROM public.knowledge_source_revisions r LOOP
        PERFORM public.assert_knowledge_revision_integrity(revision_id);
    END LOOP;
END;
$$;

REVOKE ALL ON FUNCTION public.guard_knowledge_revision(),
    public.guard_knowledge_revision_member(), public.assert_knowledge_revision_integrity(uuid),
    public.check_knowledge_revision_integrity(), public.guard_knowledge_source_policy(),
    public.check_knowledge_source_revision(), public.guard_knowledge_manifest_version(),
    public.check_knowledge_manifest_version(), public.guard_knowledge_manifest_run(),
    public.check_knowledge_manifest_run()
    FROM PUBLIC, anon, authenticated, service_role;

COMMENT ON TABLE public.knowledge_source_revisions IS
    'Reviewed audience and exact file manifest; mutations use authorized, audited backend RPCs.';
-- SOURCE workflow/authorization.sql sha256=e03aef3bc4490c7f240c67b975c4d67d99a846fbc60f1d9a50cd047770e6f23e
-- Only the trusted backend supplies actor identity. Resolve role and permission
-- provenance again in PostgreSQL; client audience selections confer no grants.
CREATE FUNCTION public.knowledge_actor_roles(actor uuid, tenant uuid, required_permission text)
RETURNS text[] LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result text[] := '{}'; role_name text;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    IF (SELECT count(DISTINCT ur.scope_id) FROM public.user_roles ur
        JOIN public.roles r ON r.id = ur.role_id
        WHERE ur.user_id = actor AND ur.scope_type = 'institution' AND r.is_active
            AND r.name IN ('admin', 'faculty', 'staff', 'student')) <> 1 THEN RETURN result; END IF;
    FOR role_name IN
        SELECT r.name FROM public.users u
        JOIN public.user_roles ur ON ur.user_id = u.id
        JOIN public.roles r ON r.id = ur.role_id
        JOIN public.role_permissions rp ON rp.role_id = r.id
        JOIN public.permissions permission ON permission.permission_id = rp.permission_id
        JOIN public.institutions i ON i.institution_id = tenant
        JOIN public.organizations o ON o.organization_id = i.organization_id
        WHERE u.id = actor AND u.status = 'active' AND r.is_active
            AND r.name IN ('admin', 'faculty', 'staff', 'student')
            AND ur.scope_type = 'institution' AND ur.scope_id = tenant
            AND ur.scope_organization_id = i.organization_id
            AND i.is_active AND i.status = 'active' AND o.status = 'active'
            AND permission.is_active AND permission.scope IN ('institution', 'global')
            AND permission.code IN (required_permission, split_part(required_permission, '.', 1) || '.*', '*')
            AND (r.name <> 'student' OR EXISTS (
                SELECT 1 FROM public.students s WHERE s.user_id = actor AND s.institution_id = tenant
                    AND s.approval_status = 'approved' AND s.is_active))
        FOR SHARE OF u, ur, r, rp, permission, i, o
    LOOP
        result := array_append(result, role_name);
    END LOOP;
    FOR role_name IN
        SELECT r.name FROM public.users u
        JOIN public.user_roles ur ON ur.user_id = u.id
        JOIN public.roles r ON r.id = ur.role_id
        JOIN public.user_permission_grants grant_row ON grant_row.user_id = u.id
        JOIN public.permissions permission ON permission.permission_id = grant_row.permission_id
        JOIN public.institutions i ON i.institution_id = tenant
        JOIN public.organizations o ON o.organization_id = i.organization_id
        WHERE u.id = actor AND u.status = 'active' AND r.name = 'staff' AND r.is_active
            AND ur.scope_type = 'institution' AND ur.scope_id = tenant
            AND ur.scope_organization_id = i.organization_id
            AND grant_row.institution_id = tenant AND grant_row.revoked_at IS NULL
            AND permission.code = required_permission AND permission.is_active
            AND permission.scope IN ('institution', 'global') AND i.is_active AND i.status = 'active' AND o.status = 'active'
        FOR SHARE OF u, ur, r, grant_row, permission, i, o
    LOOP
        result := array_append(result, role_name);
    END LOOP;
    RETURN result;
END;
$$;

CREATE FUNCTION public.assert_knowledge_actor(actor uuid, tenant uuid, permission text, administrator boolean DEFAULT false)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE roles text[];
BEGIN
    roles := public.knowledge_actor_roles(actor, tenant, permission);
    IF (administrator AND NOT 'admin' = ANY(roles))
        OR (NOT administrator AND NOT roles && ARRAY['admin', 'faculty', 'staff']) THEN
        RAISE EXCEPTION 'Resource permission required' USING ERRCODE = '42501';
    END IF;
    PERFORM pg_catalog.pg_advisory_xact_lock(pg_catalog.hashtextextended('knowledge:' || tenant::text, 0));
END;
$$;

CREATE FUNCTION public.audit_knowledge_revision(actor uuid, tenant uuid, action text, revision uuid, previous jsonb)
RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    INSERT INTO public.admin_audit_log(actor_user_id, institution_id, action, table_name, record_id, record_data)
    SELECT actor, tenant, 'knowledge.' || action, 'knowledge_source_revisions', revision::text,
        jsonb_build_object('before', previous, 'after', to_jsonb(r))
    FROM public.knowledge_source_revisions r WHERE r.revision_id = revision;
END;
$$;
-- SOURCE workflow/views.sql sha256=ec073f40fc5715758307ff9aaf73d525ffc6879df4e392c91ea29d1e1c6f6386
CREATE FUNCTION public.knowledge_revision_view(revision uuid) RETURNS jsonb
LANGUAGE sql SECURITY DEFINER SET search_path = '' AS $$
    SELECT to_jsonb(r) || jsonb_build_object(
        'policy_version', s.policy_version,
        'audience_roles', COALESCE((SELECT jsonb_agg(a.role ORDER BY a.role)
            FROM public.knowledge_source_revision_audiences a WHERE a.revision_id = r.revision_id), '[]'),
        'documents', COALESCE((SELECT jsonb_agg(jsonb_build_object(
            'document_id', v.document_id, 'document_version_id', v.document_version_id,
            'original_filename', v.original_filename, 'file_type', v.file_type,
            'version_number', v.version_number, 'file_size_bytes', v.file_size_bytes,
            'indexing_status', CASE WHEN EXISTS (SELECT 1 FROM public.document_processing_runs run
                WHERE run.document_version_id = v.document_version_id AND run.status = 'ready'
                    AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL)
                THEN 'indexed' ELSE COALESCE((SELECT CASE WHEN run.status = 'failed' OR run.embedding_status = 'failed'
                    THEN 'failed' WHEN run.status = 'queued' THEN 'queued' ELSE 'processing' END FROM public.document_processing_runs run
                    WHERE run.document_version_id = v.document_version_id ORDER BY run.created_at DESC LIMIT 1), 'queued') END
        ) ORDER BY v.original_filename)
        FROM public.knowledge_source_revision_documents m JOIN public.document_versions v USING(document_version_id)
        WHERE m.revision_id = r.revision_id), '[]'))
    FROM public.knowledge_source_revisions r
    JOIN public.knowledge_sources s USING(knowledge_source_id) WHERE r.revision_id = revision;
$$;

CREATE FUNCTION public.read_knowledge_revisions(actor uuid, tenant uuid, mode text DEFAULT 'own',
    selected_revision uuid DEFAULT NULL, page_limit integer DEFAULT 20, page_offset integer DEFAULT 0)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb;
BEGIN
    IF mode = 'review' THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.read', true);
    ELSIF mode = 'own' THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.create');
    ELSE RAISE EXCEPTION 'Unknown resource view' USING ERRCODE = '22023'; END IF;
    IF page_limit NOT BETWEEN 1 AND 100 OR page_offset NOT BETWEEN 0 AND 100000 THEN
        RAISE EXCEPTION 'Invalid pagination' USING ERRCODE = '22023';
    END IF;
    WITH permitted AS (
        SELECT r.* FROM public.knowledge_source_revisions r WHERE r.institution_id = tenant
            AND (mode = 'review' OR r.created_by_user_id = actor)
            AND (selected_revision IS NULL OR r.revision_id = selected_revision)
    ), page AS (SELECT * FROM permitted ORDER BY updated_at DESC, revision_id LIMIT page_limit OFFSET page_offset)
    SELECT jsonb_build_object('items', COALESCE((SELECT jsonb_agg(public.knowledge_revision_view(p.revision_id)
        ORDER BY p.updated_at DESC, p.revision_id) FROM page p), '[]'), 'total', (SELECT count(*) FROM permitted)) INTO result;
    IF selected_revision IS NOT NULL AND (result->>'total')::integer = 0 THEN
        RAISE EXCEPTION 'Revision not found' USING ERRCODE = 'P0002';
    END IF;
    RETURN result;
END;
$$;
-- SOURCE workflow/drafts.sql sha256=649d1bd55e52d8e6419ec65a6263ddf29fd31aabbeba12fbbd68799efae70e6c
CREATE FUNCTION public.save_knowledge_draft(actor uuid, tenant uuid, payload jsonb,
    source_id uuid DEFAULT NULL, selected_revision uuid DEFAULT NULL, expected_version bigint DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE source public.knowledge_sources; revision public.knowledge_source_revisions;
    next_row public.knowledge_source_revisions; previous jsonb; key text; role_value text;
BEGIN
    PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.create');
    IF payload IS NULL OR jsonb_typeof(payload) <> 'object' THEN
        RAISE EXCEPTION 'Metadata required' USING ERRCODE = '22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(payload) LOOP
        IF NOT key = ANY(ARRAY['title', 'description', 'source_type', 'authority_level',
            'visibility', 'audience_roles', 'effective_from', 'effective_until']) THEN
            RAISE EXCEPTION 'Unsupported metadata field' USING ERRCODE = '22023';
        END IF;
    END LOOP;
    IF source_id IS NULL THEN
        IF selected_revision IS NOT NULL THEN RAISE EXCEPTION 'Source required' USING ERRCODE = '22023'; END IF;
        INSERT INTO public.knowledge_sources(institution_id, title, description, source_type, created_by_user_id, owner_user_id)
        VALUES(tenant, payload->>'title', payload->>'description', payload->>'source_type', actor, actor)
        RETURNING * INTO source;
    ELSE
        SELECT * INTO source FROM public.knowledge_sources s
            WHERE s.knowledge_source_id = source_id AND s.institution_id = tenant FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Source not found' USING ERRCODE = 'P0002'; END IF;
        IF source.created_by_user_id IS DISTINCT FROM actor THEN
            PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
        END IF;
    END IF;
    IF COALESCE(payload->>'source_type', source.source_type) IN ('faq', 'notice') OR source.source_type IN ('faq', 'notice') THEN
        RAISE EXCEPTION 'Use the canonical editor for this source type' USING ERRCODE = '22023';
    END IF;
    IF selected_revision IS NULL THEN
        INSERT INTO public.knowledge_source_revisions(knowledge_source_id, institution_id, revision_number,
            title, description, source_type, authority_level, visibility, effective_from, effective_until, created_by_user_id)
        SELECT source.knowledge_source_id, tenant, COALESCE(max(r.revision_number), 0) + 1,
            source.title, source.description, source.source_type, source.authority_level,
            source.visibility, source.effective_from, source.effective_until, actor
        FROM public.knowledge_source_revisions r WHERE r.knowledge_source_id = source.knowledge_source_id
        RETURNING * INTO revision;
        IF source.published_revision_id IS NOT NULL THEN
            INSERT INTO public.knowledge_source_revision_audiences
                SELECT revision.revision_id, a.role FROM public.knowledge_source_revision_audiences a
                WHERE a.revision_id = source.published_revision_id;
            INSERT INTO public.knowledge_source_revision_documents
                SELECT revision.revision_id, m.knowledge_source_id, m.document_id, m.document_version_id
                FROM public.knowledge_source_revision_documents m WHERE m.revision_id = source.published_revision_id;
        END IF;
    ELSE
        SELECT * INTO revision FROM public.knowledge_source_revisions r
            WHERE r.revision_id = selected_revision AND r.knowledge_source_id = source.knowledge_source_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Revision not found' USING ERRCODE = 'P0002'; END IF;
        IF revision.created_by_user_id IS DISTINCT FROM actor THEN
            PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
        END IF;
        IF expected_version IS NULL OR revision.revision_version <> expected_version THEN
            RAISE EXCEPTION 'Revision changed; reload before saving' USING ERRCODE = '40001';
        END IF;
        IF revision.lifecycle_status <> 'draft' THEN RAISE EXCEPTION 'Draft required' USING ERRCODE = '23514'; END IF;
    END IF;
    previous := to_jsonb(revision);
    next_row := jsonb_populate_record(revision, payload - 'audience_roles');
    UPDATE public.knowledge_source_revisions r SET title = next_row.title, description = next_row.description,
        source_type = next_row.source_type, authority_level = next_row.authority_level,
        visibility = next_row.visibility, effective_from = next_row.effective_from, effective_until = next_row.effective_until
        WHERE r.revision_id = revision.revision_id;
    IF payload ? 'audience_roles' THEN
        IF jsonb_typeof(payload->'audience_roles') <> 'array' THEN
            RAISE EXCEPTION 'Role targets must be an array' USING ERRCODE = '22023';
        END IF;
        DELETE FROM public.knowledge_source_revision_audiences a WHERE a.revision_id = revision.revision_id;
        FOR role_value IN SELECT jsonb_array_elements_text(payload->'audience_roles') LOOP
            INSERT INTO public.knowledge_source_revision_audiences VALUES(revision.revision_id, role_value);
        END LOOP;
    END IF;
    PERFORM public.audit_knowledge_revision(actor, tenant, 'draft.save', revision.revision_id, previous);
    RETURN public.knowledge_revision_view(revision.revision_id);
END;
$$;
-- SOURCE workflow/uploads.sql sha256=85d05fa7fc71ddec3511cefdad152bba4bccdd1e1b072252db55daa59c86d224
CREATE FUNCTION public.register_knowledge_upload(actor uuid, tenant uuid, revision uuid,
    expected_version bigint, file_metadata jsonb, selected_document uuid DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE draft public.knowledge_source_revisions; doc_id uuid; version_id uuid; run_id uuid;
    version_number integer; previous jsonb; allowed text[] := ARRAY['original_filename', 'file_type',
        'mime_type', 'file_size_bytes', 'storage_bucket', 'storage_object_key', 'file_checksum', 'version_label']; key text;
BEGIN
    PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.create');
    PERFORM public.assert_knowledge_actor(actor, tenant,
        CASE WHEN selected_document IS NULL THEN 'documents.create' ELSE 'documents.update' END);
    SELECT * INTO draft FROM public.knowledge_source_revisions r
        WHERE r.revision_id = revision AND r.institution_id = tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Revision not found' USING ERRCODE = 'P0002'; END IF;
    IF draft.created_by_user_id IS DISTINCT FROM actor THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
    END IF;
    IF draft.lifecycle_status <> 'draft' THEN RAISE EXCEPTION 'Draft required' USING ERRCODE = '23514'; END IF;
    IF expected_version IS NULL OR draft.revision_version <> expected_version THEN
        RAISE EXCEPTION 'Revision changed' USING ERRCODE = '40001';
    END IF;
    IF file_metadata IS NULL OR jsonb_typeof(file_metadata) <> 'object' THEN
        RAISE EXCEPTION 'File metadata required' USING ERRCODE = '22023';
    END IF;
    FOR key IN SELECT jsonb_object_keys(file_metadata) LOOP
        IF NOT key = ANY(allowed) THEN RAISE EXCEPTION 'Unsupported file metadata' USING ERRCODE = '22023'; END IF;
    END LOOP;
    previous := to_jsonb(draft);
    IF selected_document IS NULL THEN
        INSERT INTO public.documents(knowledge_source_id) VALUES(draft.knowledge_source_id) RETURNING document_id INTO doc_id;
    ELSE
        SELECT d.document_id INTO doc_id FROM public.documents d
            WHERE d.document_id = selected_document AND d.knowledge_source_id = draft.knowledge_source_id FOR UPDATE;
        IF NOT FOUND THEN RAISE EXCEPTION 'Document not found' USING ERRCODE = 'P0002'; END IF;
    END IF;
    SELECT COALESCE(max(v.version_number), 0) + 1 INTO version_number
        FROM public.document_versions v WHERE v.document_id = doc_id;
    INSERT INTO public.document_versions(document_id, version_number, original_filename, file_type,
        mime_type, file_size_bytes, storage_provider, storage_bucket, storage_object_key, file_checksum, version_label, created_by_user_id)
    VALUES(doc_id, version_number, file_metadata->>'original_filename', file_metadata->>'file_type',
        file_metadata->>'mime_type', (file_metadata->>'file_size_bytes')::bigint, 'r2',
        file_metadata->>'storage_bucket', file_metadata->>'storage_object_key', file_metadata->>'file_checksum', file_metadata->>'version_label', actor)
    RETURNING document_version_id INTO version_id;
    INSERT INTO public.document_processing_runs(document_version_id, processor_name, processor_version, created_at)
        VALUES(version_id, 'knowledge-revisions', '1', clock_timestamp()) RETURNING processing_run_id INTO run_id;
    INSERT INTO public.knowledge_source_revision_documents
        VALUES(revision, draft.knowledge_source_id, doc_id, version_id)
        ON CONFLICT(revision_id, document_id) DO UPDATE SET document_version_id = EXCLUDED.document_version_id;
    PERFORM public.audit_knowledge_revision(actor, tenant, 'document.stage', revision, previous);
    RETURN jsonb_build_object('revision', public.knowledge_revision_view(revision),
        'document_id', doc_id, 'document_version_id', version_id, 'processing_run_id', run_id);
END;
$$;

CREATE FUNCTION public.retry_knowledge_index(actor uuid, tenant uuid, revision uuid,
    expected_version bigint, version_id uuid) RETURNS uuid
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE draft public.knowledge_source_revisions; run_id uuid;
BEGIN
    PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.create');
    SELECT * INTO draft FROM public.knowledge_source_revisions r
        WHERE r.revision_id = revision AND r.institution_id = tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Revision not found' USING ERRCODE = 'P0002'; END IF;
    IF draft.created_by_user_id IS DISTINCT FROM actor THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
    END IF;
    IF draft.lifecycle_status <> 'draft' THEN RAISE EXCEPTION 'Draft required' USING ERRCODE = '23514'; END IF;
    IF expected_version IS NULL OR draft.revision_version <> expected_version THEN
        RAISE EXCEPTION 'Revision changed' USING ERRCODE = '40001';
    END IF;
    IF NOT EXISTS(SELECT 1 FROM public.knowledge_source_revision_documents m
        WHERE m.revision_id = revision AND m.document_version_id = version_id) THEN
        RAISE EXCEPTION 'Version not found' USING ERRCODE = 'P0002';
    END IF;
    IF EXISTS(SELECT 1 FROM public.knowledge_source_revision_documents m
        JOIN public.knowledge_source_revisions r USING(revision_id)
        WHERE m.document_version_id = version_id AND r.lifecycle_status <> 'draft')
        OR EXISTS(SELECT 1 FROM public.document_processing_runs run
            WHERE run.document_version_id = version_id AND (run.status IN ('queued', 'processing')
                OR (run.status = 'ready' AND run.embedding_status IS DISTINCT FROM 'failed'))) THEN
        RAISE EXCEPTION 'Only failed draft indexing can be retried' USING ERRCODE = '23514';
    END IF;
    UPDATE public.knowledge_source_revisions SET updated_at = clock_timestamp() WHERE revision_id = revision;
    INSERT INTO public.document_processing_runs(document_version_id, processor_name, processor_version, created_at)
        VALUES(version_id, 'knowledge-revisions', '1', clock_timestamp()) RETURNING processing_run_id INTO run_id;
    PERFORM public.audit_knowledge_revision(actor, tenant, 'index.retry', revision, to_jsonb(draft));
    RETURN run_id;
END;
$$;
-- SOURCE workflow/review.sql sha256=da5054b4663ecc45dcbe151b0b42ca1ec8a715b0c0b80fd7007236788cec54fd
CREATE FUNCTION public.decide_knowledge_revision(actor uuid, tenant uuid, revision uuid,
    action text, expected_version bigint, expected_policy bigint DEFAULT NULL, notes text DEFAULT NULL)
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE draft public.knowledge_source_revisions; source public.knowledge_sources; previous jsonb;
BEGIN
    IF action = 'submit' THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.create');
    ELSIF action IN ('request_changes', 'approve', 'publish', 'unpublish') THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
    ELSE RAISE EXCEPTION 'Unknown review action' USING ERRCODE = '22023'; END IF;
    SELECT * INTO draft FROM public.knowledge_source_revisions r
        WHERE r.revision_id = revision AND r.institution_id = tenant FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Revision not found' USING ERRCODE = 'P0002'; END IF;
    IF action = 'submit' AND draft.created_by_user_id IS DISTINCT FROM actor THEN
        PERFORM public.assert_knowledge_actor(actor, tenant, 'ai.knowledge.update', true);
    END IF;
    IF expected_version IS NULL OR draft.revision_version <> expected_version THEN
        RAISE EXCEPTION 'Revision changed; reload before deciding' USING ERRCODE = '40001';
    END IF;
    SELECT * INTO source FROM public.knowledge_sources s
        WHERE s.knowledge_source_id = draft.knowledge_source_id FOR UPDATE;
    previous := to_jsonb(draft);
    IF action = 'submit' AND draft.lifecycle_status = 'draft' THEN
        IF EXISTS(SELECT 1 FROM public.knowledge_source_revision_documents m WHERE m.revision_id = revision
            AND NOT EXISTS(SELECT 1 FROM public.document_processing_runs run
                WHERE run.document_version_id = m.document_version_id AND run.status = 'ready'
                    AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL)) THEN
            RAISE EXCEPTION 'Complete indexing before submitting for review' USING ERRCODE = '23514';
        END IF;
        UPDATE public.knowledge_source_revisions SET lifecycle_status = 'under_review', submitted_at = clock_timestamp()
            WHERE revision_id = revision;
    ELSIF action = 'request_changes' AND draft.lifecycle_status IN ('under_review', 'approved') THEN
        IF NULLIF(btrim(notes), '') IS NULL THEN RAISE EXCEPTION 'Review feedback required' USING ERRCODE = '22023'; END IF;
        UPDATE public.knowledge_source_revisions SET lifecycle_status = 'draft', review_notes = notes
            WHERE revision_id = revision;
    ELSIF action = 'approve' AND draft.lifecycle_status = 'under_review' THEN
        UPDATE public.knowledge_source_revisions SET lifecycle_status = 'approved', reviewed_by_user_id = actor,
            approved_by_user_id = actor, reviewed_at = clock_timestamp(), approved_at = clock_timestamp(), review_notes = notes
            WHERE revision_id = revision;
    ELSIF action IN ('publish', 'unpublish') THEN
        IF expected_policy IS NULL OR source.policy_version <> expected_policy THEN
            RAISE EXCEPTION 'Live policy changed; reload before publishing' USING ERRCODE = '40001';
        END IF;
        IF action = 'publish' AND draft.lifecycle_status = 'approved' THEN
            -- Lock versions before changing lifecycle; no early purge or supersession.
            PERFORM v.document_version_id FROM public.document_versions v
                JOIN public.knowledge_source_revision_documents m USING(document_version_id)
                WHERE m.revision_id = revision ORDER BY v.document_version_id FOR UPDATE OF v;
            UPDATE public.knowledge_source_revisions SET lifecycle_status = 'superseded'
                WHERE revision_id = source.published_revision_id;
            UPDATE public.document_versions v SET lifecycle_status = 'published'
                FROM public.knowledge_source_revision_documents m
                WHERE m.revision_id = revision AND m.document_version_id = v.document_version_id;
            UPDATE public.knowledge_source_revisions SET lifecycle_status = 'published', published_at = clock_timestamp()
                WHERE revision_id = revision;
            UPDATE public.knowledge_sources SET published_revision_id = revision, title = draft.title,
                description = draft.description, source_type = draft.source_type, authority_level = draft.authority_level,
                visibility = draft.visibility, lifecycle_status = 'published', effective_from = draft.effective_from,
                effective_until = draft.effective_until, reviewed_by_user_id = actor, approved_by_user_id = actor
                WHERE knowledge_source_id = draft.knowledge_source_id;
        ELSIF action = 'unpublish' AND source.published_revision_id = revision THEN
            UPDATE public.knowledge_source_revisions SET lifecycle_status = 'archived' WHERE revision_id = revision;
            UPDATE public.knowledge_sources SET published_revision_id = NULL, lifecycle_status = 'archived'
                WHERE knowledge_source_id = draft.knowledge_source_id;
        ELSE RAISE EXCEPTION 'Invalid publication state' USING ERRCODE = '23514'; END IF;
    ELSE RAISE EXCEPTION 'Invalid review state' USING ERRCODE = '23514'; END IF;
    PERFORM public.assert_knowledge_revision_integrity(revision);
    PERFORM public.audit_knowledge_revision(actor, tenant, 'revision.' || action, revision, previous);
    RETURN public.knowledge_revision_view(revision);
END;
$$;
-- SOURCE workflow/index_guards.sql sha256=68fc0d7ad0d6698806b5393ba1f1ff5eab7a3d2e71b2a86d4cf0dab1bf82fd26
-- Legacy processing endpoints also write these tables. Freeze derived evidence
-- with its reviewed manifest, and serialize draft index changes against review.
CREATE FUNCTION public.guard_knowledge_index_content() RETURNS trigger
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE data jsonb; parent_column text; parent_id uuid; run_id uuid; version_id uuid;
    target_revision_id uuid; revision_status text;
BEGIN
    data := CASE WHEN TG_OP = 'DELETE' THEN to_jsonb(OLD) ELSE to_jsonb(NEW) END;
    parent_column := CASE WHEN TG_TABLE_NAME = 'knowledge_chunks' THEN 'processing_run_id' ELSE 'chunk_id' END;
    IF TG_OP = 'UPDATE' AND data->parent_column IS DISTINCT FROM to_jsonb(OLD)->parent_column THEN
        RAISE EXCEPTION 'Indexed evidence cannot be moved' USING ERRCODE = '23514';
    END IF;
    parent_id := (data->>parent_column)::uuid;
    IF TG_TABLE_NAME = 'knowledge_chunks' THEN
        run_id := parent_id;
    ELSE
        SELECT c.processing_run_id INTO run_id FROM public.knowledge_chunks c WHERE c.chunk_id = parent_id;
    END IF;
    SELECT run.document_version_id INTO version_id FROM public.document_processing_runs run WHERE run.processing_run_id = run_id;
    FOR target_revision_id, revision_status IN
        SELECT r.revision_id, r.lifecycle_status FROM public.knowledge_source_revisions r
        JOIN public.knowledge_source_revision_documents m USING(revision_id)
        WHERE m.document_version_id = version_id ORDER BY r.revision_id FOR UPDATE OF r
    LOOP
        IF revision_status <> 'draft' THEN
            RAISE EXCEPTION 'Reviewed indexed evidence is immutable' USING ERRCODE = '23514';
        END IF;
        UPDATE public.knowledge_source_revisions SET updated_at = clock_timestamp()
            WHERE revision_id = target_revision_id;
    END LOOP;
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER knowledge_chunk_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON public.knowledge_chunks
    FOR EACH ROW EXECUTE FUNCTION public.guard_knowledge_index_content();
CREATE TRIGGER knowledge_embedding_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON public.chunk_embeddings
    FOR EACH ROW EXECUTE FUNCTION public.guard_knowledge_index_content();
-- SOURCE readers/eligibility.sql sha256=bf1ee16254ca207e00f7a03e88c6201dbe2a188608977d0751106e41d0cdc5f8
CREATE FUNCTION public.knowledge_source_allowed(actor uuid, tenant uuid, source_id uuid, permission text DEFAULT 'ai.chat')
RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE source public.knowledge_sources; roles text[];
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    SELECT s.* INTO source FROM public.knowledge_sources s
    JOIN public.institutions i USING(institution_id)
    JOIN public.organizations o USING(organization_id)
    WHERE s.knowledge_source_id = source_id AND s.institution_id = tenant
        AND i.is_active AND i.status = 'active' AND o.status = 'active'
        AND s.lifecycle_status = 'published'
        AND (s.effective_from IS NULL OR s.effective_from <= CURRENT_DATE)
        AND (s.effective_until IS NULL OR s.effective_until >= CURRENT_DATE);
    IF NOT FOUND THEN RETURN false; END IF;
    IF source.published_revision_id IS NOT NULL AND NOT EXISTS (
        SELECT 1 FROM public.knowledge_source_revisions r
        WHERE r.revision_id = source.published_revision_id AND r.lifecycle_status = 'published'
    ) THEN RETURN false; END IF;
    IF actor IS NULL THEN RETURN source.visibility = 'public'; END IF;
    roles := public.knowledge_actor_roles(actor, tenant, permission);
    IF cardinality(roles) = 0 THEN RETURN false; END IF;
    IF source.visibility IN ('public', 'authenticated') THEN RETURN true; END IF;
    RETURN source.published_revision_id IS NOT NULL AND EXISTS (
        SELECT 1 FROM public.knowledge_source_revision_audiences target
        WHERE target.revision_id = source.published_revision_id AND target.role = ANY(roles)
    );
END;
$$;

CREATE FUNCTION public.knowledge_version_allowed(source_id uuid, version_id uuid)
RETURNS boolean LANGUAGE sql SECURITY DEFINER SET search_path = '' AS $$
    SELECT EXISTS(SELECT 1 FROM public.document_versions v
        JOIN public.documents d USING(document_id)
        JOIN public.knowledge_sources s USING(knowledge_source_id)
        WHERE s.knowledge_source_id = source_id AND v.document_version_id = version_id
            AND v.lifecycle_status = 'published'
            AND (v.effective_from IS NULL OR v.effective_from <= CURRENT_DATE)
            AND (v.effective_until IS NULL OR v.effective_until >= CURRENT_DATE)
            AND (s.published_revision_id IS NULL OR EXISTS (
                SELECT 1 FROM public.knowledge_source_revision_documents m
                WHERE m.revision_id = s.published_revision_id AND m.document_version_id = version_id))
            AND EXISTS(SELECT 1 FROM public.document_processing_runs run
                WHERE run.document_version_id = version_id AND run.status = 'ready'
                    AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL));
$$;
-- SOURCE readers/catalogue.sql sha256=2187860889a9f5623a544957395dfeaae1cf914d3129706e0c8d83f4f15bfa22
CREATE FUNCTION public.read_knowledge_resources(actor uuid, tenant uuid,
    source_id uuid DEFAULT NULL, page_limit integer DEFAULT 20, page_offset integer DEFAULT 0,
    excluded_types text[] DEFAULT '{}') RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE result jsonb; roles text[];
BEGIN
    roles := public.knowledge_actor_roles(actor, tenant, 'documents.read');
    IF cardinality(roles) = 0 THEN RAISE EXCEPTION 'Resource read permission required' USING ERRCODE = '42501'; END IF;
    IF page_limit NOT BETWEEN 1 AND 100 OR page_offset NOT BETWEEN 0 AND 100000 THEN
        RAISE EXCEPTION 'Invalid pagination' USING ERRCODE = '22023';
    END IF;
    WITH permitted AS (
        SELECT s.* FROM public.knowledge_sources s
        WHERE s.institution_id = tenant AND NOT s.source_type = ANY(excluded_types)
            AND (source_id IS NULL OR s.knowledge_source_id = source_id)
            AND public.knowledge_source_allowed(actor, tenant, s.knowledge_source_id, 'documents.read')
    ), page AS (SELECT * FROM permitted ORDER BY created_at DESC, knowledge_source_id LIMIT page_limit OFFSET page_offset)
    SELECT jsonb_build_object('total', (SELECT count(*) FROM permitted), 'items', COALESCE((
        SELECT jsonb_agg(jsonb_build_object('knowledge_source_id', p.knowledge_source_id, 'title', p.title,
            'description', p.description, 'source_type', p.source_type, 'visibility', p.visibility,
            'effective_from', p.effective_from, 'effective_until', p.effective_until,
            'policy_version', p.policy_version, 'audience_roles', COALESCE((SELECT jsonb_agg(a.role ORDER BY a.role)
                FROM public.knowledge_source_revision_audiences a WHERE a.revision_id = p.published_revision_id), '[]'),
            'documents', COALESCE((SELECT jsonb_agg(jsonb_build_object('document_id', v.document_id,
                'document_version_id', v.document_version_id, 'original_filename', v.original_filename,
                'file_type', v.file_type, 'version_number', v.version_number) ORDER BY v.original_filename)
                FROM public.documents d JOIN public.document_versions v USING(document_id)
                WHERE d.knowledge_source_id = p.knowledge_source_id
                    AND public.knowledge_version_allowed(p.knowledge_source_id, v.document_version_id)), '[]')
        ) ORDER BY p.created_at DESC, p.knowledge_source_id) FROM page p), '[]')) INTO result;
    IF source_id IS NOT NULL AND (result->>'total')::integer = 0 THEN
        RAISE EXCEPTION 'Resource not found' USING ERRCODE = 'P0002';
    END IF;
    RETURN result;
END;
$$;
-- SOURCE readers/search.sql sha256=ac816b439408f55971716afb8423ffa98175a0f18b4f65af491d621fa40f6e0f
CREATE FUNCTION public.search_audience_knowledge_chunks(actor uuid, query_embedding extensions.vector(1536),
    match_count integer, filter_institution_id uuid, filter_knowledge_source_id uuid DEFAULT NULL,
    filter_document_id uuid DEFAULT NULL, filter_document_version_id uuid DEFAULT NULL,
    filter_processing_run_id uuid DEFAULT NULL, filter_model_name text DEFAULT NULL)
RETURNS TABLE(chunk_id uuid, document_id uuid, document_version_id uuid, content_text text,
    processing_run_id uuid, chunk_sequence integer, section_title text, source_title text,
    source_type text, model_name text, distance double precision)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    IF match_count NOT BETWEEN 1 AND 20 OR filter_institution_id IS NULL OR filter_model_name IS NULL THEN
        RAISE EXCEPTION 'Invalid retrieval scope or limit' USING ERRCODE = '22023';
    END IF;
    IF actor IS NOT NULL AND cardinality(public.knowledge_actor_roles(actor, filter_institution_id, 'ai.chat')) = 0 THEN
        RAISE EXCEPTION 'Chat permission required' USING ERRCODE = '42501';
    END IF;
    RETURN QUERY SELECT chunk.chunk_id, doc.document_id, version.document_version_id, chunk.content_text,
        run.processing_run_id, chunk.chunk_sequence, chunk.section_title, source.title,
        source.source_type, embedding.model_name,
        (embedding.embedding OPERATOR(extensions.<=>) query_embedding)::double precision
    FROM public.chunk_embeddings embedding
    JOIN public.knowledge_chunks chunk USING(chunk_id)
    JOIN public.document_processing_runs run USING(processing_run_id)
    JOIN public.document_versions version USING(document_version_id)
    JOIN public.documents doc USING(document_id)
    JOIN public.knowledge_sources source USING(knowledge_source_id)
    WHERE source.institution_id = filter_institution_id
        AND public.knowledge_source_allowed(actor, filter_institution_id, source.knowledge_source_id)
        AND public.knowledge_version_allowed(source.knowledge_source_id, version.document_version_id)
        AND run.status = 'ready' AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL
        AND embedding.model_name = filter_model_name AND embedding.embedding_dimensions = 1536
        AND extensions.vector_dims(embedding.embedding) = 1536
        AND (filter_knowledge_source_id IS NULL OR source.knowledge_source_id = filter_knowledge_source_id)
        AND (filter_document_id IS NULL OR doc.document_id = filter_document_id)
        AND (filter_document_version_id IS NULL OR version.document_version_id = filter_document_version_id)
        AND (filter_processing_run_id IS NULL OR run.processing_run_id = filter_processing_run_id)
    ORDER BY embedding.embedding OPERATOR(extensions.<=>) query_embedding LIMIT match_count;
END;
$$;

CREATE OR REPLACE FUNCTION public.search_public_knowledge_chunks(
    query_embedding extensions.vector(1536), match_count integer, filter_institution_id uuid,
    filter_knowledge_source_id uuid DEFAULT NULL, filter_model_name text DEFAULT NULL)
RETURNS TABLE(chunk_id uuid, document_id uuid, document_version_id uuid, content_text text,
    processing_run_id uuid, chunk_sequence integer, section_title text, source_title text,
    source_type text, model_name text, distance double precision)
LANGUAGE sql SECURITY DEFINER SET search_path = '' AS $$
    SELECT * FROM public.search_audience_knowledge_chunks(NULL, query_embedding, match_count,
        filter_institution_id, filter_knowledge_source_id, NULL, NULL, NULL, filter_model_name);
$$;
-- SOURCE readers/history.sql sha256=0d25ba262a54bdf5f4861f92f074e5358814c7d507a2b5d57eff147bc05a8e3f
ALTER TABLE public.messages ADD COLUMN knowledge_policy jsonb;

CREATE FUNCTION public.guard_message_knowledge_policy() RETURNS trigger
LANGUAGE plpgsql SET search_path = '' AS $$
BEGIN
    IF NEW.knowledge_policy IS NOT NULL AND current_user NOT IN ('postgres', 'service_role') THEN
        RAISE EXCEPTION 'Knowledge provenance is backend-owned' USING ERRCODE = '42501';
    END IF;
    IF TG_OP = 'UPDATE' AND NEW.content_text IS DISTINCT FROM OLD.content_text THEN NEW.knowledge_policy := NULL; END IF;
    RETURN NEW;
END;
$$;
CREATE TRIGGER message_knowledge_policy_guard BEFORE INSERT OR UPDATE ON public.messages
FOR EACH ROW EXECUTE FUNCTION public.guard_message_knowledge_policy();

CREATE FUNCTION public.check_knowledge_policy(actor uuid, policy jsonb) RETURNS boolean
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE tenant uuid; source_id text; version text; version_id text;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    IF policy IS NULL OR jsonb_typeof(policy) <> 'object'
        OR jsonb_typeof(policy->'sources') IS DISTINCT FROM 'object'
        OR jsonb_typeof(policy->'versions') IS DISTINCT FROM 'object' THEN RETURN false; END IF;
    tenant := (policy->>'institution_id')::uuid;
    IF tenant IS NULL THEN RETURN false; END IF;
    IF actor IS NOT NULL AND cardinality(public.knowledge_actor_roles(actor, tenant, 'ai.chat')) = 0 THEN RETURN false; END IF;
    FOR source_id, version IN SELECT * FROM jsonb_each_text(policy->'sources') LOOP
        IF NOT EXISTS(SELECT 1 FROM public.knowledge_sources s
            WHERE s.knowledge_source_id = source_id::uuid AND s.policy_version::text = version
                AND public.knowledge_source_allowed(actor, tenant, s.knowledge_source_id)) THEN RETURN false; END IF;
    END LOOP;
    FOR version_id, source_id IN SELECT * FROM jsonb_each_text(policy->'versions') LOOP
        IF NOT policy->'sources' ? source_id
            OR NOT public.knowledge_version_allowed(source_id::uuid, version_id::uuid) THEN RETURN false; END IF;
    END LOOP;
    RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END;
$$;

CREATE FUNCTION public.snapshot_knowledge_policy(actor uuid, tenant uuid, chunks uuid[], inherited jsonb DEFAULT '{}')
RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE sources jsonb; versions jsonb; matched integer; result jsonb;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    SELECT count(DISTINCT c.chunk_id), COALESCE(jsonb_object_agg(s.knowledge_source_id::text, s.policy_version), '{}'),
        COALESCE(jsonb_object_agg(v.document_version_id::text, s.knowledge_source_id::text), '{}')
    INTO matched, sources, versions FROM public.knowledge_chunks c
    JOIN public.document_processing_runs run USING(processing_run_id)
    JOIN public.document_versions v USING(document_version_id)
    JOIN public.documents d USING(document_id)
    JOIN public.knowledge_sources s USING(knowledge_source_id)
    WHERE c.chunk_id = ANY(chunks) AND s.institution_id = tenant
        AND run.status = 'ready' AND run.embedding_status = 'embedded' AND run.completed_at IS NOT NULL
        AND public.knowledge_source_allowed(actor, tenant, s.knowledge_source_id)
        AND public.knowledge_version_allowed(s.knowledge_source_id, v.document_version_id);
    IF matched <> (SELECT count(DISTINCT id) FROM unnest(chunks) id) THEN
        RAISE EXCEPTION 'Knowledge access changed' USING ERRCODE = '40001';
    END IF;
    result := jsonb_build_object('institution_id', tenant,
        'sources', COALESCE(inherited->'sources', '{}') || sources,
        'versions', COALESCE(inherited->'versions', '{}') || versions);
    IF NOT public.check_knowledge_policy(actor, result) THEN
        RAISE EXCEPTION 'Knowledge access changed' USING ERRCODE = '40001';
    END IF;
    RETURN result;
END;
$$;
-- SOURCE readers/public.sql sha256=66750b2afd7d28043a8317ab9340053520d24f5f060bc26bc12c56e3716e258e
CREATE FUNCTION public.snapshot_public_knowledge_policy(institution_code text) RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
DECLARE tenant uuid; fingerprint text; enabled boolean;
BEGIN
    IF COALESCE(auth.role(), '') <> 'service_role' THEN
        RAISE EXCEPTION 'Trusted backend required' USING ERRCODE = '42501';
    END IF;
    SELECT i.institution_id, i.is_active AND i.status = 'active' AND o.status = 'active' INTO tenant, enabled
        FROM public.institutions i
        JOIN public.organizations o USING(organization_id)
        WHERE i.code = upper(btrim(institution_code));
    IF tenant IS NULL THEN RAISE EXCEPTION 'Institution unavailable' USING ERRCODE = 'P0002'; END IF;
    SELECT md5(COALESCE(string_agg(s.knowledge_source_id::text || ':' || s.policy_version::text || ':' ||
        v.document_version_id::text, ',' ORDER BY s.knowledge_source_id, v.document_version_id), '')) INTO fingerprint
    FROM public.knowledge_sources s JOIN public.documents d USING(knowledge_source_id)
    JOIN public.document_versions v USING(document_id)
    WHERE s.institution_id = tenant AND public.knowledge_source_allowed(NULL, tenant, s.knowledge_source_id)
        AND public.knowledge_version_allowed(s.knowledge_source_id, v.document_version_id);
    RETURN jsonb_build_object('institution_id', tenant, 'enabled', enabled, 'fingerprint', fingerprint);
END;
$$;

CREATE FUNCTION public.assert_legacy_knowledge_delete(actor uuid, tenant uuid, source_id uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = '' AS $$
BEGIN
    PERFORM public.assert_knowledge_actor(actor, tenant, 'documents.delete', true);
    IF NOT EXISTS(SELECT 1 FROM public.knowledge_sources s WHERE s.knowledge_source_id = source_id AND s.institution_id = tenant) THEN
        RAISE EXCEPTION 'Resource not found' USING ERRCODE = 'P0002';
    END IF;
    IF EXISTS(SELECT 1 FROM public.knowledge_source_revisions r WHERE r.knowledge_source_id = source_id) THEN
        RAISE EXCEPTION 'Revision-managed documents must be removed through a reviewed manifest' USING ERRCODE = '40001';
    END IF;
END;
$$;
-- SOURCE workflow/security.sql sha256=8b2dfb0e5b87cfe1b17420fa5ce852b3fdc809cb9bfcc58af6fdcd37d5310ee3
-- Helpers are never exposed as separate actor-selectable browser capabilities.
-- Indexing writes use trigger-owned access only to advance/check revision
-- invariants; direct application table mutation remains denied.
-- Deferred checks run after the writer's SECURITY DEFINER context has ended.
-- Own their helper calls without granting direct helper execution to the caller.
ALTER FUNCTION public.check_knowledge_revision_integrity() SECURITY DEFINER;
ALTER FUNCTION public.check_knowledge_source_revision() SECURITY DEFINER;
ALTER FUNCTION public.guard_knowledge_manifest_version() SECURITY DEFINER;
ALTER FUNCTION public.check_knowledge_manifest_version() SECURITY DEFINER;
ALTER FUNCTION public.check_knowledge_manifest_run() SECURITY DEFINER;
ALTER FUNCTION public.guard_knowledge_manifest_run() SECURITY DEFINER;
REVOKE ALL ON FUNCTION
    public.knowledge_actor_roles(uuid,uuid,text), public.assert_knowledge_actor(uuid,uuid,text,boolean),
    public.audit_knowledge_revision(uuid,uuid,text,uuid,jsonb), public.knowledge_revision_view(uuid),
    public.read_knowledge_revisions(uuid,uuid,text,uuid,integer,integer),
    public.save_knowledge_draft(uuid,uuid,jsonb,uuid,uuid,bigint),
    public.register_knowledge_upload(uuid,uuid,uuid,bigint,jsonb,uuid),
    public.retry_knowledge_index(uuid,uuid,uuid,bigint,uuid),
    public.decide_knowledge_revision(uuid,uuid,uuid,text,bigint,bigint,text),
    public.knowledge_source_allowed(uuid,uuid,uuid,text), public.knowledge_version_allowed(uuid,uuid),
    public.read_knowledge_resources(uuid,uuid,uuid,integer,integer,text[]),
    public.search_audience_knowledge_chunks(uuid,extensions.vector,integer,uuid,uuid,uuid,uuid,uuid,text),
    public.search_public_knowledge_chunks(extensions.vector,integer,uuid,uuid,text),
    public.guard_message_knowledge_policy(), public.check_knowledge_policy(uuid,jsonb),
    public.snapshot_knowledge_policy(uuid,uuid,uuid[],jsonb), public.snapshot_public_knowledge_policy(text),
    public.assert_legacy_knowledge_delete(uuid,uuid,uuid), public.guard_knowledge_index_content()
FROM PUBLIC, anon, authenticated, service_role;
GRANT EXECUTE ON FUNCTION
    public.read_knowledge_revisions(uuid,uuid,text,uuid,integer,integer),
    public.save_knowledge_draft(uuid,uuid,jsonb,uuid,uuid,bigint),
    public.register_knowledge_upload(uuid,uuid,uuid,bigint,jsonb,uuid),
    public.retry_knowledge_index(uuid,uuid,uuid,bigint,uuid),
    public.decide_knowledge_revision(uuid,uuid,uuid,text,bigint,bigint,text),
    public.read_knowledge_resources(uuid,uuid,uuid,integer,integer,text[]),
    public.search_audience_knowledge_chunks(uuid,extensions.vector,integer,uuid,uuid,uuid,uuid,uuid,text),
    public.search_public_knowledge_chunks(extensions.vector,integer,uuid,uuid,text),
    public.check_knowledge_policy(uuid,jsonb), public.snapshot_knowledge_policy(uuid,uuid,uuid[],jsonb),
    public.snapshot_public_knowledge_policy(text), public.assert_legacy_knowledge_delete(uuid,uuid,uuid)
TO service_role;
NOTIFY pgrst, 'reload schema';
COMMIT;
